options.css:
/* Reset básico */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

/* Centraliza todo o conteúdo na tela */
body {
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100vh;
    background-color: #f5f5f5;
}

/* Contêiner dos botões */
.button-container {
    display: flex;
    flex-direction: column;
    gap: 20px;
    align-items: center; /* Centraliza os botões */
}

/* Linhas de botões */
.button-row {
    display: flex;
    justify-content: center;
    gap: 20px;
}

/* Estilo dos botões */
.button {
    padding: 0.6rem 1.5rem;
    background-color: #dddddd;
    color: #000000;
    font-weight: bold;
    font-size: 15px;
    border-radius: 9999px;
    text-decoration: none;
    min-width: 170px;
    text-align: center;
    transition: all 0.3s ease-in-out;
    box-shadow: 0px 4px 8px rgba(0, 0, 0, 0.2);
}

/* Efeito hover */
.button:hover {
    transform: scale(1.05);
    border-color: #fff9;
}

/* Responsividade */
@media (max-width: 768px) {
    .button-row {
        flex-direction: column; /* Empilha os botões no celular */
        gap: 10px;
    }
}

options.onInit:
// Sets the text from customProperties
const htmlgraphicsText = htmlNode.getElementById('htmlgraphics-text');

if (htmlgraphicsText) {
  htmlgraphicsText.textContent = customProperties.text;

  // Change the text color based on the theme
  if (theme.isDark) {
    htmlgraphicsText.style.color = 'green';
  } else {
    htmlgraphicsText.style.color = 'red';
  }
}

options.onRender:
// Sets the value from the first series on every refresh
const htmlgraphicsValue = htmlNode.getElementById('htmlgraphics-value');

if (htmlgraphicsValue) {
  const valueField = data.series[0]?.fields[1];
  if (valueField) {
    const length = valueField.values.length;
    htmlgraphicsValue.textContent = valueField.values.get(length - 1);
  } else {
    htmlgraphicsValue.textContent = "No data"
  }
}
